    { const char * tb_v2764 = "static void tb_dreindex(tb_dict *d, long long nslots) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2764; }
    { const char * tb_v2765 = "    d->mode = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v2765; }
